@Route("contact")
public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
    private final MessageStore messageStore;
    private final TextField nameField;
    private final EmailField emailField;
    private final TextField phoneField;
    private final TextArea messageField;
    private final Button sendButton;
    private final Grid<Message> grid;
    private boolean formHasChanges = false;

    @Autowired
    public ContactView(MessageStore messageStore) {
        this.messageStore = messageStore;

        H1 heading = new H1("Contact");
        Anchor aboutLink = new Anchor("about", "About");
        aboutLink.setRouterLink(true);

        nameField = new TextField("Name");
        emailField = new EmailField("Email");
        phoneField = new TextField("Phone");
        messageField = new TextArea("Message");
        messageField.setMaxLength(500);

        sendButton = new Button("Send");

        FormLayout formLayout = new FormLayout();
        formLayout.add(nameField, emailField, phoneField, messageField);
        formLayout.setColspan(messageField, 2);

        grid = new Grid<>(Message.class);
        grid.setColumns("name", "messageText");
        grid.getColumnByKey("messageText").setHeader("Message");
        grid.setItems(messageStore.getMessages());

        // Track changes to form fields
        nameField.addValueChangeListener(e -> {
            formHasChanges = true;
            sendButton.setEnabled(true);
        });
        emailField.addValueChangeListener(e -> {
            formHasChanges = true;
            sendButton.setEnabled(true);
        });
        phoneField.addValueChangeListener(e -> {
            formHasChanges = true;
            sendButton.setEnabled(true);
        });
        messageField.addValueChangeListener(e -> {
            formHasChanges = true;
            sendButton.setEnabled(true);
        });

        // Send button click handler
        sendButton.addClickListener(e -> handleSend());

        // Allow pressing Enter in message field to send
        messageField.addKeyDownListener(com.vaadin.flow.component.Key.ENTER, e -> {
            if (sendButton.isEnabled()) {
                handleSend();
            }
        });

        add(heading, aboutLink, formLayout, sendButton, grid);
        setPadding(true);
        setSpacing(true);
    }

    private void handleSend() {
        // Validate form
        boolean isValid = validateForm();

        if (!isValid) {
            return;
        }

        // Create and store message
        Message message = new Message(
            nameField.getValue(),
            emailField.getValue(),
            phoneField.getValue(),
            messageField.getValue()
        );

