@@ -0,0 +1,225 @@
+package com.example;
+
+import com.vaadin.flow.component.Component;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import org.springframework.beans.factory.annotation.Autowired;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private final MessageStore messageStore;
+    private final TextField nameField;
+    private final EmailField emailField;
+    private final TextField phoneField;
+    private final TextArea messageField;
+    private final Button sendButton;
+    private final Grid<Message> grid;
+    private BeforeLeaveEvent pendingLeaveEvent;
+
+    @Autowired
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        H1 heading = new H1("Contact");
+
+        Button aboutButton = new Button("About");
+        aboutButton.addClickListener(e -> navigateIfSafe(AboutView.class));
+
+        nameField = new TextField("Name");
+        emailField = new EmailField("Email");
+        phoneField = new TextField("Phone");
+        messageField = new TextArea("Message");
+        messageField.setMaxLength(500);
+
+        sendButton = new Button("Send");
+
+        FormLayout formLayout = new FormLayout();
+        formLayout.add(nameField, emailField, phoneField, messageField);
+        formLayout.setColspan(messageField, 2);
+
+        grid = new Grid<>(Message.class);
+        grid.setColumns("name", "messageText");
+        grid.getColumnByKey("messageText").setHeader("Message");
+        grid.setItems(messageStore.getMessages());
+
+        // Track changes to form fields
+        nameField.addValueChangeListener(e -> sendButton.setEnabled(true));
+        emailField.addValueChangeListener(e -> sendButton.setEnabled(true));
+        phoneField.addValueChangeListener(e -> sendButton.setEnabled(true));
+        messageField.addValueChangeListener(e -> sendButton.setEnabled(true));
+
+        // Send button click handler
+        sendButton.addClickListener(e -> handleSend());
+
+        // Allow pressing Enter in message field to send
+        messageField.addKeyDownListener(com.vaadin.flow.component.Key.ENTER, e -> {
+            if (sendButton.isEnabled()) {
+                handleSend();
+            }
+        });
+
+        add(heading, aboutButton, formLayout, sendButton, grid);
+        setPadding(true);
+        setSpacing(true);
+    }
+
+    private void navigateIfSafe(Class<?> target) {
+        if (hasUnsavedData()) {
+            showUnsavedDialog(() -> {
+                @SuppressWarnings("unchecked")
+                Class<? extends Component> navTarget = (Class<? extends Component>) target;
+                UI.getCurrent().navigate(navTarget);
+            });
+        } else {
+            @SuppressWarnings("unchecked")
+            Class<? extends Component> navTarget = (Class<? extends Component>) target;
+            UI.getCurrent().navigate(navTarget);
+        }
+    }
+
+    private void showUnsavedDialog(Runnable onDiscard) {
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Unsaved changes");
+
+        Button keepEditingButton = new Button("Keep editing", e -> dialog.close());
+        Button discardButton = new Button("Discard", e -> {
+            dialog.close();
+            if (pendingLeaveEvent != null) {
+                pendingLeaveEvent.forwardTo(AboutView.class);
+            } else {
+                onDiscard.run();
+            }
+        });
+
+        dialog.getFooter().add(keepEditingButton, discardButton);
+        dialog.open();
+    }
+
+    private void handleSend() {
+        // Validate form
+        boolean isValid = validateForm();
+
+        if (!isValid) {
+            return;
+        }
+
+        // Create and store message
+        Message message = new Message(
+            nameField.getValue(),
+            emailField.getValue(),
+            phoneField.getValue(),
+            messageField.getValue()
+        );
+        messageStore.addMessage(message);
+
+        // Show notification
+        Notification notification = new Notification("Message sent", 3000);
+        notification.open();
+
+        // Clear form
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+
+        // Disable send button until next edit
+        sendButton.setEnabled(false);
+
+        // Update grid
+        grid.setItems(messageStore.getMessages());
+    }
+
+    private boolean validateForm() {
+        boolean isValid = true;
+
+        // Clear all error messages first
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        phoneField.setInvalid(false);
+        messageField.setInvalid(false);
+
+        // Validate name
+        if (nameField.getValue().trim().isEmpty()) {
+            nameField.setInvalid(true);
+            nameField.setErrorMessage("Name is required");
+            isValid = false;
+        }
+
+        // Validate email and phone
+        String email = emailField.getValue().trim();
+        String phone = phoneField.getValue().trim();
+
+        if (!email.isEmpty() && !isValidEmail(email)) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            isValid = false;
+        }
+
+        if (email.isEmpty() && phone.isEmpty()) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            isValid = false;
+        }
+
+        // Validate message
+        String message = messageField.getValue();
+        if (message.trim().isEmpty()) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message is required");
+            isValid = false;
+        } else if (message.length() > 500) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            isValid = false;
+        }
+
+        return isValid;
+    }
+
+    private boolean isValidEmail(String email) {
+        return email.matches("^[A-Za-z0-9+_.-]+@(.+)$");
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsavedData()) {
+            event.postpone();
+            pendingLeaveEvent = event;
+
+            Dialog dialog = new Dialog();
+            dialog.setHeaderTitle("Unsaved changes");
+
+            Button keepEditingButton = new Button("Keep editing", e -> {
+                dialog.close();
+                pendingLeaveEvent = null;
+            });
+            Button discardButton = new Button("Discard", e -> {
+                dialog.close();
+                // ForwardTo will navigate without re-triggering beforeLeave with the same state
+                event.forwardTo(AboutView.class);
+            });
+
+            dialog.getFooter().add(keepEditingButton, discardButton);
+            dialog.open();
+        }
+    }
+
+    private boolean hasUnsavedData() {
+        return !nameField.getValue().isEmpty() ||
+               !emailField.getValue().isEmpty() ||
+               !phoneField.getValue().isEmpty() ||
+               !messageField.getValue().isEmpty();
+    }
+}
