+package com.example;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.test.context.TestPropertySource;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+@SpringBootTest
+@TestPropertySource(properties = "server.port=8080")
+class ContactViewTest {
+
+    @Autowired
+    private MessageStore messageStore;
+
+    @Test
+    void contextLoads() {
+        assertNotNull(messageStore);
+    }
+
+    @Test
+    void messageStoreAddMessage() {
+        Message msg = new Message("John", "john@example.com", "123-456", "Hello");
+        messageStore.addMessage(msg);
+
+        assertTrue(messageStore.getMessages().size() > 0);
+        assertEquals("John", messageStore.getMessages().get(0).getName());
+    }
+
+    @Test
+    void messageStoreNewestFirst() {
+        int initialSize = messageStore.getMessages().size();
+
+        Message msg1 = new Message("John", "john@example.com", "123-456", "First");
+        Message msg2 = new Message("Jane", "jane@example.com", "789-012", "Second");
+
+        messageStore.addMessage(msg1);
+        messageStore.addMessage(msg2);
+
+        assertEquals(initialSize + 2, messageStore.getMessages().size());
+        assertEquals("Jane", messageStore.getMessages().get(0).getName());
+        assertEquals("John", messageStore.getMessages().get(1).getName());
+    }
+}
